"""Tests for the portable generated-C -> guest-VA source map."""
import io
import json
import tempfile
import unittest
from contextlib import redirect_stdout
from pathlib import Path

from tools.autorecomp import source_map


UNIT_1 = """\
/* Auto-generated by XWA recompiler - DO NOT EDIT */
#include "recomp_types.h"
#include "recomp_funcs.h"

void sub_00401000(void) {
    /* 0x00401000: a brace in a comment } */
    g_eax = 1;
    sprintf(g_buf, "{not a body end}");
    if (g_eflags & 0x40) { g_eax = 2; }
}

void sub_00401020(void) {
    g_eax = g_eax + 1;
}
"""

UNIT_2 = """\
/* Auto-generated by XWA recompiler - DO NOT EDIT */
#include "recomp_types.h"
#include "recomp_funcs.h"

void sub_00401030__lowlevel(void) {
    g_eax = 3;
}

void sub_00401030(void) {
    sub_00401030__lowlevel();
}
"""

DISPATCH = """\
/* Auto-generated dispatch table - DO NOT EDIT */

#include "recomp_types.h"
#include "recomp_funcs.h"

const recomp_dispatch_entry_t recomp_dispatch_table[] = {
    { 0x00401000u, sub_00401000 },
    { 0x00401020u, sub_00401020 },
    { 0x00401030u, sub_00401030 },
};

const uint32_t recomp_dispatch_count = 3;
"""

HEADER = """\
/* Auto-generated function declarations - DO NOT EDIT */
#pragma once
#include <stdint.h>

void sub_00401000(void);  /* 0x00401000 */
void sub_00401020(void);  /* 0x00401020 */
void sub_00401030(void);  /* 0x00401030 */
void sub_00401030__lowlevel(void);  /* 0x00401030 mechanical fallback */
"""


class SourceMapTest(unittest.TestCase):
    def setUp(self):
        self.tmp = tempfile.TemporaryDirectory()
        self.root = Path(self.tmp.name)
        self.project = self.root / "project"
        self.gen = self.project / "src" / "recomp" / "gen"
        self.gen.mkdir(parents=True)
        self.write_defaults()

    def tearDown(self):
        self.tmp.cleanup()

    def write_defaults(self):
        (self.gen / "recomp_0000.c").write_text(UNIT_1)
        (self.gen / "recomp_0001.c").write_text(UNIT_2)
        (self.gen / "recomp_dispatch.c").write_text(DISPATCH)
        (self.gen / "recomp_funcs.h").write_text(HEADER)
        (self.gen / "recomp_units.json").write_text('{"schema": 1, "units": []}')

    def build(self):
        return source_map.build_source_map(self.project)

    def by_address(self, document, address):
        return next(f for f in document["functions"] if f["address"] == address)

    # -- happy path ---------------------------------------------------------

    def test_maps_each_definition_and_dispatch_entry_to_file_line(self):
        doc = self.build()
        self.assertEqual(doc["schema"], source_map.SCHEMA_VERSION)
        self.assertEqual(doc["gen_dir"], "src/recomp/gen")
        self.assertEqual(len(doc["functions"]), 3)
        self.assertEqual(len(doc["source_map"]), 3)

        first = self.by_address(doc, "0x00401000")
        self.assertEqual(first["definition"]["file"], "src/recomp/gen/recomp_0000.c")
        self.assertEqual(first["definition"]["symbol"], "sub_00401000")
        self.assertEqual(first["definition"]["line"], 5)
        self.assertEqual(first["dispatch"]["file"], "src/recomp/gen/recomp_dispatch.c")
        self.assertEqual(first["dispatch"]["line"], 7)
        self.assertEqual(first["header"]["line"], 5)
        self.assertEqual(first["definition"]["end_line"], 10)

        # The flat Stela-style rows are (guest_va, file, line).
        self.assertEqual(doc["source_map"][0], {
            "guest_va": "0x00401000",
            "file": "src/recomp/gen/recomp_0000.c",
            "line": 5,
            "symbol": "sub_00401000",
        })

    def test_lowlevel_fallback_is_recorded_beside_entry(self):
        doc = self.build()
        fn = self.by_address(doc, "0x00401030")
        self.assertEqual(fn["definition"]["symbol"], "sub_00401030")
        self.assertEqual(fn["definition"]["kind"], "entry")
        self.assertEqual(fn["fallback_definition"]["symbol"],
                         "sub_00401030__lowlevel")
        self.assertEqual(fn["fallback_definition"]["kind"], "fallback")
        self.assertEqual(fn["dispatch"]["symbol"], "sub_00401030")
        self.assertEqual(fn["definition_count"], 2)

    def test_valid_project_has_no_violations_and_full_coverage(self):
        doc = self.build()
        self.assertEqual(doc["violations"], [])
        cov = source_map.coverage(doc)
        self.assertEqual(cov["mapped"], 3)
        self.assertEqual(cov["expected"], 3)
        self.assertEqual(cov["percent"], 100.0)
        self.assertEqual(cov["dropped_addresses"], [])
        self.assertEqual(cov["unmatched_definition_addresses"], [])

    def test_portability_paths_are_relative_and_posix(self):
        doc = self.build()
        blob = json.dumps(doc)
        self.assertNotIn(str(self.root), blob)
        self.assertNotIn(str(self.project), blob)
        for path in doc["files"]:
            self.assertFalse(path.startswith("/"))
            self.assertNotIn("\\", path)
        self.assertEqual(doc["gen_dir"], "src/recomp/gen")

    def test_artifact_hash_tracks_generated_content(self):
        base = self.build()["artifact_sha256"]
        with (self.gen / "recomp_0000.c").open("a") as f:
            f.write("\n/* changed */\n")
        self.assertNotEqual(self.build()["artifact_sha256"], base)

    # -- named violations ---------------------------------------------------

    def test_missing_definition_is_a_named_violation(self):
        dispatch = DISPATCH.replace(
            "    { 0x00401030u, sub_00401030 },",
            "    { 0x00401030u, sub_00401030 },\n"
            "    { 0x00401040u, sub_00401040 },")
        dispatch = dispatch.replace("recomp_dispatch_count = 3",
                                    "recomp_dispatch_count = 4")
        (self.gen / "recomp_dispatch.c").write_text(dispatch)
        doc = self.build()
        self.assertTrue(any(v.startswith("missing_definition: 0x00401040")
                            for v in doc["violations"]), doc["violations"])
        self.assertIn("0x00401040", doc["coverage"]["dropped_addresses"])
        self.assertLess(doc["coverage"]["percent"], 100.0)

    def test_missing_dispatch_is_a_named_violation(self):
        (self.gen / "recomp_dispatch.c").write_text(DISPATCH.replace(
            "    { 0x00401020u, sub_00401020 },\n", ""))
        doc = self.build()
        self.assertTrue(any(v.startswith("missing_dispatch: 0x00401020")
                            for v in doc["violations"]), doc["violations"])

    def test_symbol_address_mismatch_is_a_named_violation(self):
        dispatch = DISPATCH.replace("0x00401000u, sub_00401000",
                                    "0x00401000u, sub_00409999")
        (self.gen / "recomp_dispatch.c").write_text(dispatch)
        doc = self.build()
        self.assertTrue(any(v.startswith("symbol_address_mismatch: 0x00401000")
                            for v in doc["violations"]), doc["violations"])

    def test_non_monotonic_dispatch_address_is_a_named_violation(self):
        lines = DISPATCH.splitlines(keepends=True)
        # Swap the first two entries so table addresses (and lines) decrease.
        lines[6], lines[7] = lines[7], lines[6]
        (self.gen / "recomp_dispatch.c").write_text("".join(lines))
        doc = self.build()
        self.assertTrue(any(v.startswith("non_monotonic_dispatch_address")
                            for v in doc["violations"]), doc["violations"])

    def test_declared_count_mismatch_is_a_named_violation(self):
        (self.gen / "recomp_dispatch.c").write_text(DISPATCH.replace(
            "recomp_dispatch_count = 3", "recomp_dispatch_count = 9"))
        doc = self.build()
        self.assertTrue(any(v.startswith("dispatch_count_mismatch")
                            for v in doc["violations"]), doc["violations"])

    def test_duplicate_dispatch_is_a_named_violation(self):
        dispatch = DISPATCH.replace(
            "    { 0x00401000u, sub_00401000 },",
            "    { 0x00401000u, sub_00401000 },\n"
            "    { 0x00401000u, sub_00401000 },")
        (self.gen / "recomp_dispatch.c").write_text(dispatch)
        doc = self.build()
        self.assertTrue(any(v.startswith("duplicate_dispatch: 0x00401000")
                            for v in doc["violations"]), doc["violations"])

    def test_unbalanced_body_is_a_named_violation(self):
        # Remove only the brace closing the first function's body.
        broken = UNIT_1.replace(
            "    if (g_eflags & 0x40) { g_eax = 2; }\n}\n",
            "    if (g_eflags & 0x40) { g_eax = 2; }\n", 1)
        (self.gen / "recomp_0000.c").write_text(broken)
        doc = self.build()
        self.assertTrue(any(v.startswith("unbalanced_body: 0x00401000")
                            for v in doc["violations"]), doc["violations"])

    # -- discovery and CLI --------------------------------------------------

    def test_find_gen_dir_accepts_bare_gen_directory(self):
        self.assertEqual(source_map.find_gen_dir(self.gen), self.gen.resolve())
        self.assertEqual(
            source_map.find_gen_dir(self.project),
            (self.project / "src" / "recomp" / "gen").resolve())

    def test_find_gen_dir_rejects_empty_tree(self):
        empty = self.root / "empty"
        empty.mkdir()
        with self.assertRaises(ValueError):
            source_map.find_gen_dir(empty)

    def test_cli_writes_json_file(self):
        out = self.root / "reports" / "source_map.json"
        rc = source_map.main(["--project-dir", str(self.project),
                              "--output", str(out)])
        self.assertEqual(rc, 0)
        doc = json.loads(out.read_text())
        self.assertEqual(len(doc["functions"]), 3)

    def test_cli_defaults_to_stdout_and_fail_on_violation(self):
        buf = io.StringIO()
        with redirect_stdout(buf):
            rc = source_map.main(["--project-dir", str(self.project)])
        self.assertEqual(rc, 0)
        self.assertEqual(len(json.loads(buf.getvalue())["source_map"]), 3)

        (self.gen / "recomp_dispatch.c").write_text(DISPATCH.replace(
            "    { 0x00401020u, sub_00401020 },\n", ""))
        with redirect_stdout(io.StringIO()):
            rc = source_map.main(["--project-dir", str(self.project),
                                  "--fail-on-violation"])
        self.assertEqual(rc, 1)


if __name__ == "__main__":
    unittest.main()
